 static void Main(string[] args){string ffmpeg=args.Length>1?Path.GetFullPath(args[1]):"/usr/bin/ffmpeg";string root=Path.GetFullPath(args[0]),undo=Path.Combine(root,"undo");var paths=new[]{"glen.mp3","wilson.mp3"}.Select(x=>Path.Combine(root,x)).ToArray();var songs=paths.Select(MediaMetadata.Read).ToArray();var originals=paths.Select(File.ReadAllBytes).ToArray();string cover=Path.Combine(root,"cover.png"),second=Path.Combine(root,"second.jpg");
 Check(AppIdentity.Version=="v0.64","Versionskennung");
