 using(var f=TagLib.File.Create(paths[0])){f.Tag.Comment="Extern geändert";TagLib.Id3v2.UserTextInformationFrame.Get((TagLib.Id3v2.Tag)f.GetTag(TagLib.TagTypes.Id3v2,true),"CUSTOM_KEEP",true).Text=new[]{"Erhalten"};f.Save();}
 var plan=MetadataFilePlan.Create(songs,new Dictionary<string,string>{{"artist","Björk"},{"genre","(2)"},{"year","2026"}});
 Check(plan.Count==2&&!plan[0].Fields.ContainsKey("album")&&!plan[0].Fields.ContainsKey("comment"),"Speicherplan enthält nur beabsichtigte Felder");var action=FileTagAction.Apply(plan,undo);
 for(int i=0;i<2;i++){using(var f=TagLib.File.Create(paths[i])){Check(f.Tag.Performers.Single()=="Björk"&&f.Tag.Genres.Single()=="Country"&&f.Tag.Year==2026,"Unicode, Jahr und Genre direkt in Datei "+i);var t=(TagLib.Id3v2.Tag)f.GetTag(TagLib.TagTypes.Id3v2,false);Check(TagLib.Id3v2.TextInformationFrame.Get(t,"TCON",false).Text.Single()=="Country","TCON enthält Text statt Zahl "+i);if(i==0){Check(f.Tag.Comment=="Extern geändert"&&f.Tag.Album=="Country","Nicht bearbeitete Tags bleiben erhalten");Check(TagLib.Id3v2.UserTextInformationFrame.Get(t,"CUSTOM_KEEP",false).Text.Single()=="Erhalten","Unbekannte Tags bleiben erhalten");}}}
 var beforeCover=paths.Select(File.ReadAllBytes).ToArray();var art=FileTagAction.Apply(EmbeddedArtwork.Plan(songs,cover),undo);for(int i=0;i<2;i++)Check(MediaMetadata.Artwork(paths[i]).SequenceEqual(File.ReadAllBytes(cover)),"Eingebettetes APIC nach erneutem Öffnen "+i);
 art.Restore(false);Check(paths.Select((x,i)=>File.ReadAllBytes(x).SequenceEqual(beforeCover[i])).All(x=>x),"Cover-Rücknahme bytegenau");art.Restore(true);
 var added=FileTagAction.Apply(EmbeddedArtwork.Plan(songs,second,true),undo);Check(paths.All(x=>{using(var f=TagLib.File.Create(x))return f.Tag.Pictures.Length==2;}),"Zusätzliches Cover für Mehrfachauswahl");
 var replaced=FileTagAction.Apply(EmbeddedArtwork.Plan(songs,cover,false),undo);Check(paths.All(x=>{using(var f=TagLib.File.Create(x))return f.Tag.Pictures.Length==1;}),"Frontcover ersetzen");
 var current=paths.Select(File.ReadAllBytes).ToArray();Reject(()=>FileTagAction.Apply(MetadataFilePlan.Create(songs,new Dictionary<string,string>{{"year","kaputt"}}),undo),"Ungültige Eingabe abweisen");Check(paths.Select((x,i)=>File.ReadAllBytes(x).SequenceEqual(current[i])).All(x=>x),"Ungültige Tags ändern keine Originaldatei");
 songs[0].PendingTags=new Dictionary<string,string>{{"title","Noch nicht gespeicherter Titel"}};var pending=MetadataFilePlan.Create(new[]{songs[0]},new Dictionary<string,string>{{"genre","Rock"}});FileTagAction.Apply(pending,undo);Check(songs[0].Title=="Noch nicht gespeicherter Titel"&&songs[0].PendingTags.Count==0,"Vorgemerkte Änderung wird gespeichert und bestätigt");
 var track=TrackNumbering.Plan(songs,3,true,true,false);FileTagAction.Apply(track,undo);Check(TagFields.Read(paths[0])["track"]=="03/2"&&TagFields.Read(paths[1])["track"]=="04/2","Track-Assistent beachtet Auswahlreihenfolge und Nullen");
 Check(MetadataFilePlan.Create(new[]{songs[0],songs[0]},new Dictionary<string,string>()).Count==1,"Speicherpfade dedupliziert");
 Reject(()=>FileTagAction.Apply(MetadataFilePlan.Create(songs,new Dictionary<string,string>{{"_directory","X"}}),undo),"Ordnerinformationen sind keine ID3-Tags");
