 Check(OutputFormatSettings.Keys("%title% / %artist% / %_directory% / %artist%").SequenceEqual(new[]{"title","artist","_directory"}),"Sichtbare Felder in Format-Reihenfolge");
 var project=new Project();project.Folders.Add(new BoxFolder{Name="000 Alt",Theme="Alt",Songs=new List<Song>{songs[0]}});var batch=new Project();batch.Folders.Add(new BoxFolder{Name="000 Neu",Theme="Neu",Songs=new List<Song>{songs[0].Copy(),songs[1]}});HashSet<string> addedPaths;var merged=LibraryBatch.Merge(project,batch,out addedPaths);Check(merged.Folders.SelectMany(f=>f.Songs).Count()==2&&addedPaths.Count==1&&project.Folders.Count==1,"Import-Merge erhält Bibliothek und dedupliziert Pfade");
 foreach(int quality in new[]{4,2,1,0})Check(AudioAdvanced.EncoderArgs(new AudioOptions{Format="MP3",Vbr=true,Quality=quality}).Contains("-q:a "+quality),"MP3-VBR-Stufe V"+quality);
 Check(AudioAdvanced.EncoderArgs(new AudioOptions{Format="MP3",Vbr=false,Bitrate=192}).Contains("-b:a 192k"),"CBR separat");
 Reject(()=>VideoAudioImport.Validate("file:///tmp/audio.mp3"),"Lokale URL als Videolink abweisen");Reject(()=>VideoAudioImport.Validate("https://user:pass@example.com/video"),"Eingebettete Zugangsdaten abweisen");Check(VideoAudioImport.Validate("https://example.com/video").Host=="example.com","HTTP-Quelle validieren");
 if(args.Contains("--mit-medien")){ string output=Path.Combine(root,"output");Directory.CreateDirectory(output);byte[] videoHash=Hash(Path.Combine(root,"local.mp4"));var video=MediaProbe57.Read(Path.Combine(root,"local.mp4"),ffmpeg,()=>{});Check(video.Duration>0,"Lokales Video mit Audiospur einlesen");string extracted=AudioAdvanced.ExtractOriginal(new[]{video},output,ffmpeg,()=>{},(n,total,t)=>{});Check(Directory.GetFiles(extracted,"*.m4a").Length==1,"AAC ohne Neukodierung extrahieren");Check(Hash(video.Source).SequenceEqual(videoHash),"Originalvideo bleibt unverändert");
 string converted=AudioAdvanced.FfmpegBatch(new[]{video},output,ffmpeg,new AudioOptions{Format="MP3",Vbr=true,Quality=2},()=>{},(n,total,t)=>{});Check(Directory.GetFiles(converted,"*.mp3").Any(f=>MediaMetadata.Read(f).Duration>0),"Video in MP3 V2 konvertieren");
