}
 // A project restart preserves pending changes without sharing mutable dictionaries.
 songs[0].PendingTags=new Dictionary<string,string>{{"genre","Jazz"}};var copy=songs[0].Copy();copy.PendingTags["genre"]="Pop";Check(songs[0].PendingTags["genre"]=="Jazz","Kopierte Änderungen sind unabhängig");
