 foreach(byte version in new byte[]{3,4}){string path=Path.Combine(root,"genre-v2"+version+".mp3");File.WriteAllBytes(path,originals[0]);using(var file=TagLib.File.Create(path)){((TagLib.Id3v2.Tag)file.GetTag(TagLib.TagTypes.Id3v2,true)).Version=version;file.Tag.Genres=new[]{"Country"};file.Save();}var item=MediaMetadata.Read(path);FileTagAction.Apply(MetadataFilePlan.Create(new[]{item},new Dictionary<string,string>{{"genre","2"}}),undo);FileTagAction.Apply(EmbeddedArtwork.Plan(new[]{item},cover),undo);using(var file=TagLib.File.Create(path)){var tag=(TagLib.Id3v2.Tag)file.GetTag(TagLib.TagTypes.Id3v2,false);Check(tag.Version==version&&TagLib.Id3v2.TextInformationFrame.Get(tag,"TCON",false).Text.Single()=="Country"&&file.Tag.Pictures.Length==1,"ID3v2."+version+" erhält Version, Genretext und APIC");}}
 string v1=Path.Combine(root,"id3v1-only.mp3");File.WriteAllBytes(v1,originals[0]);using(var f=TagLib.File.Create(v1)){f.RemoveTags(TagLib.TagTypes.Id3v2);f.GetTag(TagLib.TagTypes.Id3v1,true);f.Tag.Title="ID3v1";f.Save();}FileTagAction.Apply(MetadataFilePlan.Create(new[]{MediaMetadata.Read(v1)},new Dictionary<string,string>{{"genre","Country"}}),undo);using(var f=TagLib.File.Create(v1))Check(f.Tag.Genres.Contains("Country")&&f.GetTag(TagLib.TagTypes.Id3v2,false)!=null,"ID3v1-Datei erhält kompatiblen Genretext in ID3v2");
 Console.WriteLine("BESTANDEN: "+count);
